local TreadleHammerMaker = {}
local PRODUCTS = {
    iron_treadlehammer = { name = "Železni pedalno kladivo", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni pedalno kladivo za kovace." },
    bronze_treadlehammer = { name = "Bronast pedalno kladivo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast pedalno kladivo za kovace." },
    silver_treadlehammer = { name = "Srebrn pedalno kladivo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn pedalno kladivo za kovace." },
    gilded_treadlehammer = { name = "Pozlačen pedalno kladivo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen pedalno kladivo za kovace." },
    jewel_set_treadlehammer = { name = "Draguljast pedalno kladivo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast pedalno kladivo za kovace." },
    royal_sovereign_treadlehammer = { name = "Kraljevski suveren pedalno kladivo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren pedalno kladivo z biseri za krono." },
}
local BUILDINGS = {
    treadlehammer_workshop = { name = "Treadlehammer delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    treadlehammer_house = { name = "Treadlehammer hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_treadlehammer_atelier = { name = "Mojstrski treadlehammer atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_treadlehammer_palace = { name = "Suverena treadlehammer palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
TreadleHammerMaker.ironStock=16; TreadleHammerMaker.bronzeStock=12; TreadleHammerMaker.woodStock=14; TreadleHammerMaker.leatherStock=10; TreadleHammerMaker.silverStock=8; TreadleHammerMaker.goldStock=6; TreadleHammerMaker.jewelStock=4; TreadleHammerMaker.pearlStock=4
TreadleHammerMaker.productStock = {}; TreadleHammerMaker.buildings = {}; TreadleHammerMaker.maker = nil; TreadleHammerMaker.activeMaking = {}; TreadleHammerMaker.totalProducts = 0; TreadleHammerMaker.dayTimer = 0
function TreadleHammerMaker.init() TreadleHammerMaker.ironStock=16; TreadleHammerMaker.bronzeStock=12; TreadleHammerMaker.woodStock=14; TreadleHammerMaker.leatherStock=10; TreadleHammerMaker.silverStock=8; TreadleHammerMaker.goldStock=6; TreadleHammerMaker.jewelStock=4; TreadleHammerMaker.pearlStock=4; TreadleHammerMaker.productStock={}; TreadleHammerMaker.buildings={}; TreadleHammerMaker.maker=nil; TreadleHammerMaker.activeMaking={}; TreadleHammerMaker.totalProducts=0; TreadleHammerMaker.dayTimer=0; print("[TreadleHammerMaker] Royal Treadle Hammer Maker System initialized (6 products, 4 buildings)") end
function TreadleHammerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TreadleHammerMaker.maker={name=n or ("Pedalar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pedalar najet: %s (spretnost: %d)",TreadleHammerMaker.maker.name,s),"success") end; return true end
function TreadleHammerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TreadleHammerMaker.build(id) local ok,e=TreadleHammerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TreadleHammerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TreadleHammerMaker.getQualityBonus() local b=0; for _,bd in ipairs(TreadleHammerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TreadleHammerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and TreadleHammerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and TreadleHammerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and TreadleHammerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and TreadleHammerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and TreadleHammerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TreadleHammerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TreadleHammerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TreadleHammerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TreadleHammerMaker.buildings==0 then return false,"Potrebna pedalna delavnica" end; if not TreadleHammerMaker.maker then return false,"Potreben pedalar" end; return true end
function TreadleHammerMaker.make(pt,qty) qty=qty or 1; local ok,e=TreadleHammerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then TreadleHammerMaker.ironStock=TreadleHammerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then TreadleHammerMaker.bronzeStock=TreadleHammerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then TreadleHammerMaker.woodStock=TreadleHammerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then TreadleHammerMaker.leatherStock=TreadleHammerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then TreadleHammerMaker.silverStock=TreadleHammerMaker.silverStock-d.silverCost*qty end; if d.goldCost then TreadleHammerMaker.goldStock=TreadleHammerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TreadleHammerMaker.jewelStock=TreadleHammerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TreadleHammerMaker.pearlStock=TreadleHammerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TreadleHammerMaker.maker then t=math.max(1,t-math.floor(TreadleHammerMaker.maker.skill/13)) end; table.insert(TreadleHammerMaker.activeMaking,{id="treadlehammer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TreadleHammerMaker.completeMaking(m) local q=1.0+(TreadleHammerMaker.getQualityBonus()/100); if TreadleHammerMaker.maker then q=q+(TreadleHammerMaker.maker.skill/140) end; q=math.min(2.5,q); TreadleHammerMaker.productStock[m.productType]=(TreadleHammerMaker.productStock[m.productType] or 0)+m.quantity; TreadleHammerMaker.totalProducts=TreadleHammerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TreadleHammerMaker.maker then TreadleHammerMaker.maker.itemsMade=TreadleHammerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TreadleHammerMaker.maker.skill=math.min(100,TreadleHammerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kladivo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"treadlehammer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function TreadleHammerMaker.update(dt) if not _G.state then return end; TreadleHammerMaker.dayTimer=TreadleHammerMaker.dayTimer+dt; if TreadleHammerMaker.dayTimer>=30 then TreadleHammerMaker.dayTimer=0; for i=#TreadleHammerMaker.activeMaking,1,-1 do local m=TreadleHammerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TreadleHammerMaker.completeMaking(m); table.remove(TreadleHammerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TreadleHammerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TreadleHammerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TreadleHammerMaker.getStats() return {ironStock=TreadleHammerMaker.ironStock,bronzeStock=TreadleHammerMaker.bronzeStock,woodStock=TreadleHammerMaker.woodStock,leatherStock=TreadleHammerMaker.leatherStock,silverStock=TreadleHammerMaker.silverStock,goldStock=TreadleHammerMaker.goldStock,jewelStock=TreadleHammerMaker.jewelStock,pearlStock=TreadleHammerMaker.pearlStock,productStock=TreadleHammerMaker.productStock,numBuildings=#TreadleHammerMaker.buildings,hasMaker=TreadleHammerMaker.maker~=nil,makerName=TreadleHammerMaker.maker and TreadleHammerMaker.maker.name or "—",makerSkill=TreadleHammerMaker.maker and TreadleHammerMaker.maker.skill or 0,activeMaking=#TreadleHammerMaker.activeMaking,totalProducts=TreadleHammerMaker.totalProducts} end
return TreadleHammerMaker
